				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$mat_id = intval($deleted_values["id"]);

$rsCur = DB::Query("SELECT COUNT(*) AS total FROM cursos WHERE materia_id = " . $mat_id);
$rCur = $rsCur->fetchAssoc();
if (intval($rCur["total"]) > 0) {
    $message = "No es posible eliminar la asignatura porque se encuentra asignada a cátedras activas o históricas.";
    return false;
}

$rsMalla = DB::Query("SELECT COUNT(*) AS total FROM carrera_materia WHERE materia_id = " . $mat_id);
$rMalla = $rsMalla->fetchAssoc();
if (intval($rMalla["total"]) > 0) {
    $message = "La materia forma parte de la malla curricular de una o más carreras. Quítela de la malla antes de eliminarla.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



